"""Public PHASA narrative: client challenge, approach, delivery and next phase.
Source proposals and training materials remain private and are not bundled here.
"""

def build_story(t, p, heading, section, cards, bullets):
    title=t('PHASA: SEO, GEO e IA para marketing y ventas','PHASA: SEO, GEO and AI for marketing and sales')
    desc=t('Cómo Mood conectó la estrategia SEO/GEO de PHASA con capacitación en IA para marketing y ventas, HubSpot, Breeze y un plan de automatización comercial.','How Mood connected PHASA’s SEO/GEO strategy with AI training for marketing and sales, HubSpot, Breeze and a sales automation roadmap.')
    hero=p('PHASA · Industria B2B · Transformación digital en curso','PHASA · B2B industry · Digital transformation in progress','eyebrow')
    hero+='<h1>PHASA.<br><span>'+t('SEO, GEO e IA para conectar marketing y ventas.','SEO, GEO and AI to connect marketing and sales.')+'</span></h1>'
    hero+=p('PHASA buscaba mejorar su posicionamiento digital, aprovechar la IA y automatizar procesos. Mood planteó una estrategia que une visibilidad en buscadores, formación de los equipos y seguimiento comercial en HubSpot.','PHASA wanted to improve its digital visibility, put AI to work and automate processes. Mood developed a strategy combining search visibility, team training and sales follow-up in HubSpot.','lede')
    hero+='<div class="md-hero-actions"><a class="btn" href="#reto">'+t('Conocer el reto y la solución ↓','Explore the challenge and solution ↓')+'</a><a class="btn secondary" href="/contacto/" data-cta="phasa-hero">'+t('Hablemos de tu proyecto','Let’s discuss your project')+'</a></div><dl class="md-facts">'
    for a,b,c,d in [('Cliente','Client','PHASA','PHASA'),('Industria','Industry','Soluciones de hule · B2B','Rubber solutions · B2B'),('Mercado','Market','México','Mexico'),('Alcance','Scope','SEO/GEO + IA + HubSpot + capacitación','SEO/GEO + AI + HubSpot + training')]:
        hero+='<div><dt>'+t(a,b)+'</dt><dd>'+t(c,d)+'</dd></div>'
    hero+='</dl><figure class="ph-cover"><img src="/assets/casos/phasa/project-cover.svg" width="1400" height="760" fetchpriority="high" alt="'+t('PHASA: estrategia digital, contenido, equipos y CRM conectados','PHASA: connected digital strategy, content, teams and CRM')+'"><figcaption>'+t('El proyecto combina estrategia, formación y diseño de procesos para acompañar la transformación de PHASA.','The project combines strategy, training and process design to support PHASA’s transformation.')+'</figcaption></figure>'
    body='<article class="md-case ph-case"><section class="md-hero"><div class="wrap">'+hero+'</div></section><nav class="md-index" aria-label="'+t('Secciones del caso PHASA','PHASA case sections')+'"><div class="wrap">'
    for id,es,en in [('reto','El reto','The challenge'),('estrategia','La estrategia','The strategy'),('visibilidad','SEO y GEO','SEO and GEO'),('marketing','Marketing con IA','AI for marketing'),('crm','Ventas y HubSpot','Sales and HubSpot'),('automatizacion','Automatización','Automation'),('avance','Avances','Progress')]:
        body+=f'<a href="#{id}">'+t(es,en)+'</a>'
    body+='</div></nav>'

    challenge=heading('01 / El problema del cliente','Una empresa con experiencia. Una oportunidad de conectar su operación digital.','01 / The client’s challenge','An established business. An opportunity to connect its digital operations.')
    challenge+=p('PHASA es una empresa mexicana especializada en productos de hule y materiales para aplicaciones industriales. Contaba con un catálogo técnico, campañas activas, un equipo comercial con experiencia y HubSpot en operación. Su siguiente paso era aprovechar mejor esos recursos.','PHASA is a Mexican company specializing in rubber products and materials for industrial applications. It already had a technical catalog, active campaigns, an experienced sales team and HubSpot in use. Its next step was to make better use of those resources.')
    challenge+=p('El cliente planteó tres necesidades relacionadas: ganar visibilidad en Google y en las respuestas de herramientas de IA; reducir tareas manuales mediante inteligencia artificial; y fortalecer el uso del CRM para dar continuidad a cada oportunidad comercial.','The client identified three related needs: gain visibility on Google and in AI-generated answers; use artificial intelligence to reduce manual work; and make stronger use of its CRM to follow through on sales opportunities.')
    challenge+=cards([
        ('Posicionamiento por mejorar','Search visibility to strengthen','La auditoría encontró demanda orgánica y páginas con visibilidad, pero también oportunidades para mejorar los clics, organizar el contenido por intención de compra y explicar mejor las aplicaciones de los productos.','The audit found organic demand and pages already appearing in search, alongside opportunities to improve click-through, organize content around buying intent and explain product applications more clearly.'),
        ('Captación y ventas por conectar','Connect acquisition with sales','La medición mezclaba acciones de distinto valor. Hacía falta distinguir una visita o un clic de un lead válido, y relacionar la captación con el avance de las oportunidades en HubSpot.','Measurement combined actions of different business value. Visits and clicks needed to be distinguished from valid leads, and acquisition needed to be connected with deal progress in HubSpot.'),
        ('IA aplicada al trabajo diario','AI applied to daily work','Marketing y comercial necesitaban aprender a usar la IA sobre sus tareas reales: producir contenido técnico, analizar información, preparar seguimientos y mantener actualizado el CRM.','Marketing and sales needed practical AI skills for their work: producing technical content, analyzing information, preparing follow-ups and keeping the CRM up to date.')])
    body+=section('reto',challenge,True)

    strategy=heading('02 / El planteamiento de Mood','Trabajar la tecnología y la adopción del equipo al mismo tiempo.','02 / Mood’s approach','Develop the technology and team adoption together.')
    strategy+=p('Propusimos abordar el proyecto en dos frentes paralelos: mejorar la base digital de PHASA y hule.com.mx, y capacitar a las personas que producen contenido, atienden prospectos y gestionan oportunidades. Así, el posicionamiento y la automatización tendrían un proceso comercial y un equipo preparados para sostenerlos.','We proposed two parallel workstreams: improve the digital foundation of PHASA and hule.com.mx, and train the people who produce content, respond to prospects and manage opportunities. Search visibility and automation would then be supported by a clear sales process and a team able to use it.')
    strategy+=cards([
        ('Diagnosticar','Diagnose','Revisar buscadores, analítica, campañas y CRM para entender dónde había demanda, qué se estaba midiendo y qué impedía dar un seguimiento consistente.','Review search performance, analytics, campaigns and the CRM to understand demand, measurement and the obstacles to consistent follow-up.'),
        ('Diseñar y entrenar','Design and train','Definir la arquitectura SEO/GEO y los procesos de trabajo; enseñar al equipo a aplicar IA con contexto de marca, información técnica y datos comerciales.','Define SEO/GEO architecture and working processes; teach the team to apply AI using brand context, technical information and sales data.'),
        ('Automatizar por prioridades','Automate by priority','Identificar tareas repetitivas y establecer reglas, responsables y controles antes de integrar canales o activar flujos automáticos.','Identify repetitive tasks and establish rules, owners and controls before integrating channels or activating automated workflows.')])
    strategy+='<blockquote class="md-pull">'+t('La estrategia debía cubrir el recorrido completo: que el comprador encuentre a PHASA, entienda la solución y reciba un seguimiento comercial claro.','The strategy needed to cover the full journey: help buyers find PHASA, understand the solution and receive clear sales follow-up.')+'</blockquote>'
    body+=section('estrategia',strategy)

    seo=heading('03 / La solución: posicionamiento','Convertir el conocimiento técnico en contenido que ayude a encontrar y elegir a PHASA.','03 / The solution: search visibility','Turn technical expertise into content that helps buyers find and choose PHASA.')
    seo+=p('Partimos de la auditoría de Google Analytics, Search Console y Google Ads. La lectura conjunta permitió identificar categorías con demanda y orientar la estrategia hacia las preguntas de compra del mercado industrial: qué material elegir, para qué aplicación sirve y qué características debe cumplir.','We started with an audit of Google Analytics, Search Console and Google Ads. Reviewing them together helped identify categories with demand and focus the strategy on industrial buying questions: which material to choose, what application it serves and which specifications matter.')
    seo+='<div class="md-pair"><div><h3>'+t('SEO: responder a la intención de búsqueda','SEO: address search intent')+'</h3>'+p('Se diseñó una arquitectura para hule.com.mx por categorías, productos y aplicaciones. Preparamos páginas prioritarias, guías técnicas, títulos, descripciones y una propuesta de enlaces internos para que el comprador avance desde su necesidad hasta la solicitud de cotización.','We designed an architecture for hule.com.mx organized by categories, products and applications. Priority pages, technical guides, titles, descriptions and an internal linking plan were prepared to help buyers move from a need to a quote request.')+'</div><div><h3>'+t('GEO: facilitar la comprensión por la IA','GEO: make the information easier for AI to understand')+'</h3>'+p('La estrategia también contempla cómo se presenta la información a los motores de respuesta con IA: explicaciones directas, preguntas frecuentes, comparaciones de materiales y datos estructurados. El objetivo es facilitar que esas herramientas interpreten el contenido técnico y puedan usarlo como referencia.','The strategy also addresses how information is presented to AI answer engines: direct explanations, frequently asked questions, material comparisons and structured data. The aim is to help those tools interpret the technical content and use it as a reference.')+'</div></div>'
    seo+=p('El trabajo editorial preparado incluye una página de inicio, una página piloto, seis páginas de categoría y cinco guías, junto con preguntas frecuentes y lineamientos de publicación. Su implementación se organiza por etapas, con validación técnica del cliente.','The prepared editorial work includes a home page, a pilot page, six category pages and five guides, together with FAQs and publishing guidelines. Implementation is organized in stages, with the client validating technical information.')
    seo+=p('La medición se planteó con una lógica comercial: diferenciar interacciones de leads válidos y dar seguimiento al paso de lead a oportunidad y venta.','Measurement was designed around business outcomes: distinguish interactions from valid leads and track progress from lead to opportunity and sale.')
    body+=section('visibilidad',seo,True)

    marketing=heading('04 / La solución: equipo de marketing','Entrenar al equipo para producir, analizar y trabajar con IA.','04 / The solution: marketing team','Train the team to create, analyze and work with AI.')
    marketing+=p('La estrategia de posicionamiento necesitaba un equipo capaz de sostenerla. Por eso impartimos formación aplicada al contexto de PHASA, con sesiones, ejercicios y guías para utilizar IA en estrategia de contenido, análisis y tareas recurrentes.','The search strategy needed a team able to sustain it. We delivered training tailored to PHASA, using sessions, exercises and guides to apply AI to content strategy, analysis and recurring tasks.')
    marketing+=cards([
        ('Dar contexto antes de crear','Provide context before creating','Se trabajó con brief de marca, perfiles de compradores, problemas, objeciones y etapas de compra. Esa base se utilizó para orientar mensajes, contenidos y llamados a la acción con ChatGPT y Claude.','Training covered brand briefs, buyer profiles, problems, objections and buying stages. This foundation guided messages, content and calls to action using ChatGPT and Claude.'),
        ('Crear procesos reutilizables','Build repeatable processes','Con Claude y Cowork se enseñó a organizar documentos, crear instrucciones reutilizables —skills— y conectar herramientas. Las prácticas incluyeron auditorías, consulta de datos, planificación de campañas y gestión de archivos.','With Claude and Cowork, the team learned to organize documents, create reusable instructions—skills—and connect tools. Practice covered audits, data queries, campaign planning and file management.'),
        ('Analizar y revisar con criterio','Analyze and review critically','Se demostraron consultas de analítica e interpretación de comportamiento con Clarity. El entrenamiento incorporó revisión humana, validación técnica y permisos de acceso para usar la IA sobre información de trabajo.','Sessions demonstrated analytics queries and behavior analysis with Clarity. Training included human review, technical validation and access permissions for using AI with work information.')])
    marketing+=p('El propósito era dejar una metodología que el equipo pudiera repetir: contexto de marca → necesidad del comprador → contenido o análisis → revisión → siguiente acción. Los materiales de apoyo permiten retomar el proceso después de cada sesión.','The aim was to leave the team with a repeatable method: brand context → buyer need → content or analysis → review → next action. Supporting materials let participants return to the process after each session.')
    body+=section('marketing',marketing)

    sales=heading('05 / La solución: equipo comercial','Usar HubSpot y Breeze para convertir el historial en próximas acciones.','05 / The solution: sales team','Use HubSpot and Breeze to turn customer history into next actions.')
    sales+=p('PHASA ya utilizaba HubSpot. El reto era aprovecharlo mejor en el seguimiento cotidiano: mantener etapas y fechas útiles, registrar el contexto de las conversaciones y asegurar que cada oportunidad tuviera un responsable y una siguiente acción.','PHASA was already using HubSpot. The challenge was to make better use of it in daily follow-up: maintain useful stages and dates, record conversation context and ensure every opportunity has an owner and a next action.')
    sales+=p('A partir de la revisión del CRM, el entrenamiento comercial se llevó al trabajo del vendedor y del gerente. El programa incluyó IA aplicada a HubSpot, con Breeze —la IA de HubSpot— y el uso de Claude o ChatGPT mediante conectores autorizados, según las funciones disponibles en el portal.','Following the CRM review, sales training focused on the daily work of salespeople and managers. The program covered AI applied to HubSpot, including Breeze—HubSpot’s AI—and Claude or ChatGPT through authorized connectors, depending on the features available in the portal.')
    sales+='<h3 class="md-space">'+t('Del contacto al cierre: un proceso común','From contact to close: a shared process')+'</h3><ol class="ph-roadmap">'
    for n,es,en,desc_es,desc_en in [
        ('01','Contacto','Contact','Buscar y registrar al cliente sin duplicar información.','Find and record the customer without duplicating information.'),
        ('02','Oportunidad','Opportunity','Crear el negocio y asignar a la persona responsable.','Create the deal and assign an owner.'),
        ('03','Cotización','Quote','Registrar valor, referencia y una fecha de cierre realista.','Record the value, reference and a realistic close date.'),
        ('04','Seguimiento','Follow-up','Programar la siguiente tarea y guardar el contexto.','Schedule the next task and record the context.'),
        ('05','Cierre','Close','Actualizar el resultado y documentar el motivo de pérdida cuando corresponda.','Update the outcome and record the loss reason when applicable.')]:
        sales+='<li><span class="ph-step">'+n+'</span><div><h4>'+t(es,en)+'</h4>'+p(desc_es,desc_en)+'</div></li>'
    sales+='</ol>'+cards([
        ('IA para el vendedor','AI for salespeople','Ejercicios para priorizar pendientes, encontrar cotizaciones sin seguimiento, resumir el historial antes de una llamada, preparar mensajes y transformar notas en registros estructurados.','Exercises for prioritizing tasks, finding quotes without follow-up, summarizing history before a call, preparing messages and turning notes into structured records.'),
        ('IA para el gerente','AI for managers','Prompts y una rutina de revisión del pipeline para identificar oportunidades detenidas, analizar motivos de pérdida y definir acciones por vendedor con base en los datos del CRM.','Prompts and a pipeline review routine to identify stalled opportunities, analyze loss reasons and define actions for each salesperson using CRM data.'),
        ('Práctica con control','Controlled practice','Guías, ejercicios de edición por lotes y tareas entre sesiones. Primero se consulta y revisa la información; los cambios se validan con el responsable del proceso.','Guides, batch-editing exercises and assignments between sessions. Information is queried and reviewed first; changes are validated with the process owner.')])
    body+=section('crm',sales,True)

    automation=heading('06 / Automatización de procesos','Diseñar qué se automatiza, con qué datos y quién interviene.','06 / Process automation','Define what to automate, which data it needs and who takes over.')
    automation+=p('La formación y el orden del CRM son la base del AI Sales Operating System propuesto para PHASA: una arquitectura que conecte captación, atención, cotización, seguimiento y análisis. El trabajo de diagnóstico y diseño permite priorizar los flujos antes de configurarlos.','Training and CRM discipline form the foundation of the AI Sales Operating System proposed for PHASA: an architecture connecting acquisition, response, quotation, follow-up and analysis. Diagnosis and design help prioritize workflows before they are configured.')
    automation+='<div class="md-pair"><div><h3>'+t('Automatizaciones priorizadas','Priority automations')+'</h3>'+bullets([
        ('Crear una tarea de seguimiento al enviar una cotización.','Create a follow-up task when a quote is sent.'),
        ('Avisar cuando una oportunidad queda sin actividad.','Flag opportunities with no recent activity.'),
        ('Detectar fechas de cierre vencidas para revisarlas.','Identify overdue close dates for review.'),
        ('Preparar un resumen semanal del pipeline para el gerente.','Prepare a weekly pipeline summary for the manager.')])+'</div><div><h3>'+t('Evolución del sistema comercial','Evolution of the sales system')+'</h3>'+p('El diseño contempla integrar atención por WhatsApp con IA, calificación de solicitudes, derivación al asesor, evolución del cotizador existente y tableros de seguimiento. Cada componente tiene una función dentro del recorrido comercial y una activación por etapas.','The design includes AI-assisted WhatsApp response, request qualification, routing to a salesperson, development of the existing quotation tool and reporting dashboards. Each component has a defined role in the sales journey and a staged rollout.')+'</div></div>'
    automation+=p('Estos flujos forman parte de la propuesta de implementación. Su activación depende de la validación de PHASA, la calidad de los datos y las capacidades contratadas. El objetivo es reducir tareas repetitivas y permitir que los asesores dediquen más tiempo a entender necesidades y acompañar decisiones de compra.','These workflows form part of the implementation proposal. Activation depends on PHASA’s validation, data quality and licensed capabilities. The goal is to reduce repetitive tasks so salespeople can spend more time understanding needs and supporting buying decisions.')
    body+=section('automatizacion',automation)

    progress=heading('07 / Avances del proyecto','Una estrategia común y equipos preparados para llevarla al trabajo diario.','07 / Project progress','A shared strategy and teams trained to put it into daily practice.')
    progress+=p('El trabajo realizado reúne diagnóstico digital, arquitectura y contenido SEO/GEO, formación en IA para marketing y entrenamiento comercial con HubSpot. La conexión entre estos frentes es el aporte central de Mood: definir cómo atraer demanda relevante, cómo trabajarla y cómo preparar su seguimiento para la automatización.','The work delivered brings together digital diagnosis, SEO/GEO architecture and content, AI training for marketing and sales training with HubSpot. Connecting these workstreams is Mood’s central contribution: defining how to attract relevant demand, work with it and prepare follow-up for automation.')
    progress+=cards([
        ('Estrategia y contenidos preparados','Strategy and content prepared','Diagnóstico de canales, arquitectura SEO-comercial, contenidos técnicos y lineamientos para publicar por prioridades.','Channel diagnosis, a search-led commercial architecture, technical content and guidelines for prioritized publishing.'),
        ('Formación aplicada a dos equipos','Applied training for two teams','Marketing trabajó contexto, contenido, análisis y procesos con IA. Comercial trabajó seguimiento, datos y productividad sobre HubSpot.','Marketing worked on context, content, analysis and AI-supported processes. Sales worked on follow-up, data and productivity in HubSpot.'),
        ('Ruta de automatización definida','Automation roadmap defined','Procesos, tareas y oportunidades de integración identificados para avanzar de la capacitación a la implementación por etapas.','Processes, tasks and integration opportunities identified to progress from training to staged implementation.')])
    progress+=p('Proyecto en curso · Actualizado al 20 de noviembre de 2026. Las sesiones y entregables descritos están documentados; la publicación de contenidos y las automatizaciones avanzan por etapas. El impacto en posicionamiento, productividad y ventas se evaluará con medición posterior.','Project in progress · Updated November 20, 2026. The sessions and deliverables described are documented; content publication and automation progress in stages. Impact on search visibility, productivity and sales will be evaluated through subsequent measurement.','note')
    body+=section('avance',progress,True)
    close=heading('Marketing + ventas + tecnología','¿Tu empresa necesita conectar estos mismos procesos?','Marketing + sales + technology','Does your business need to connect these processes?')
    close+=p('Podemos ayudarte a identificar dónde se pierde continuidad entre la captación y la venta, qué necesita aprender tu equipo y qué procesos conviene automatizar con IA.','We can help identify gaps between acquisition and sales, the skills your team needs and the processes worth automating with AI.')
    close+='<div class="actions"><a class="btn" href="/contacto/" data-cta="phasa-closing">'+t('Conversemos sobre tu empresa','Let’s discuss your business')+'</a><a class="btn secondary" href="https://www.phasa.mx/" target="_blank" rel="noopener noreferrer">'+t('Visitar PHASA ↗','Visit PHASA ↗')+'</a></div>'
    body+=section('contactar',close)+'</article>'
    return body,title,desc
